m=math;Pi=m.pi;Tau=m.pi*2;Inf=m.huge;Deg=m.pi/180;Sin=m.sin;Cos=m.cos;Tan=m.tan;Acos=m.acos;Asin=m.asin;Atan=m.atan;Sqrt=m.sqrt;Max=m.max;Min=m.min;Floor=m.floor;Ceil=m.ceil;Abs=m.abs;function Clamp(a,b,c)return Min(Max(a,b),c)end;function Lerp(d,e,f)return d+(e-d)*f end;function Map(f,d,e,g,h)return(f-d)/(e-d)*(h-g)+g end;function Round(d)return Floor(d+0.5)end;function Vec(i,j,k)return{x=i,y=j,z=k}end;function Add(l,n)return{x=l.x+n.x,y=l.y+n.y,z=l.z+n.z}end;function Sub(l,n)return{x=l.x-n.x,y=l.y-n.y,z=l.z-n.z}end;function Scale(l,o)return{x=l.x*o,y=l.y*o,z=l.z*o}end;function Dot(l,n)return l.x*n.x+l.y*n.y+l.z*n.z end;function Cross(l,n)return{x=l.y*n.z-l.z*n.y,y=l.z*n.x-l.x*n.z,z=l.x*n.y-l.y*n.x}end;function Len(l)return Sqrt(l.x*l.x+l.y*l.y+l.z*l.z)end;function SetLen(l,o)return Scale(Norm(l),o)end;function Norm(l)return Len(l)~=0 and Scale(l,1/Len(l))or{x=0,y=0,z=0}end;function Lerp(l,n,f)return Add(l,Scale(Sub(n,l),f))end;function IJK(p,q,r)local s,t,u=Cos(p),Cos(q),Cos(r)local v,w,x=Sin(p),Sin(q),Sin(r)return Vec(Vec(t*u,t*x,-w),Vec(-s*x+v*w*u,s*u+v*w*x,v*t),Vec(s*w*u+v*x,s*w*x-v*u,s*t))end;function Local(l,y)return Vec(Dot(l,y.x),Dot(l,y.y),Dot(l,y.z))end;function Global(l,y)return Add(Scale(y.x,l.x),Add(Scale(y.y,l.y),Scale(y.z,l.z)))end;function Sphere(l)return Vec(Atan(l.x,l.z),Atan(l.y,l.z),Len(l))end;function Cartesian(l)local z=Cos(l.x)<0 and-1 or 1;local A=Vec(Sin(l.x)*Cos(l.y)*z,Sin(l.y)*Cos(l.x)*z,Cos(l.x)*Cos(l.y)*z)return Scale(Norm(A),l.z)end;RADAR_TYPE=property.getNumber("Input Type")RADAR_PRIORITY=property.getNumber("Prioritise")TOLERANCE=property.getNumber("Tolerance")function onTick()has_target=false;guidance=Vec(0,0,0)if RADAR_TYPE==0 then guidance.x=input.getNumber(1)guidance.y=input.getNumber(2)if input.getNumber(1)~=0 or input.getNumber(2)~=0 then has_target=true end else GPS=Vec(input.getNumber(4),input.getNumber(8),input.getNumber(12))targets={}if input.getBool(1)==true then has_target=true;for B=1,8 do if input.getBool(B*4-3)then distance=input.getNumber(B*4-3)radarX=input.getNumber(B*4-2)radarY=input.getNumber(B*4-1)targets[B]=Vec(radarX,radarY,distance)last_locked=B end end;if RADAR_PRIORITY==0 then guidance=targets[1]elseif RADAR_PRIORITY==1 then lowest=Inf;candidate=Vec(0,0,0)for target in targets do deviation=Len(Sub(Cartesian(target),GPS))if deviation<lowest then candidate=target end end;guidance=candidate elseif RADAR_PRIORITY==2 then lowest=Inf;candidate=Vec(0,0,0)for target in targets do deviation=target.z;if deviation<lowest then candidate=target end end;guidance=candidate elseif RADAR_PRIORITY==3 then guidance=targets[last_locked]elseif RADAR_PRIORITY==4 then for B=#targets,1,-1 do target=targets[B]deviation=Len(Sub(Cartesian(target),GPS))if deviation<TOLERANCE then guidance=target end end end end end;output.setNumber(1,guidance.x)output.setNumber(2,guidance.y)output.setBool(1,has_target)end